    print('true' if word_break_brute(s, words) else 'false')

import sys
from functools import lru_cache

def word_break_opt(s, words):
    @lru_cache(maxsize=None)
    def dfs(rest):
        if not rest:
            return True
        for w in words:
            if rest.startswith(w) and dfs(rest[len(w):]):
                return True
        return False
    return dfs(s)

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    s = data[0]
    m = int(data[1])
    words = data[2:2 + m]
    print('true' if word_break_opt(s, words) else 'false')

import sys

def word_break_best(s, words):
    n = len(s)
    word_set = set(words)
    dp = [False] * (n + 1)
    dp[0] = True
    for i in range(1, n + 1):
        for j in range(i):
            if dp[j] and s[j:i] in word_set:
                dp[i] = True
                break
    return dp[n]

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    s = data[0]
    m = int(data[1])
    words = data[2:2 + m]
    print('true' if word_break_best(s, words) else 'false')
